    const r = await c.keyword(t("pc.prompt.option"), { options: [opt7("S", "Slice"), opt7("H", "Height"), opt7("T", "Thickness"), opt7("C", "Color"), opt7("SI", "Size"), opt7("V", "Visible"), opt7("Z", "Zoom"), opt7("D", "Detach")] });
